const EventEmitter = require('events');
const bridge = process._linkedBinding('rn_bridge');

class Channel extends EventEmitter {
  constructor() {
    super();
    // Register the native callback to emit events on this JS object
    bridge.registerChannel('message', (channel, msg) => {
      this.emit('message', msg);
      // Support for named events if sent in the message
      try {
        const parsed = JSON.parse(msg);
        if (parsed.event) {
          this.emit(parsed.event, parsed.data || parsed.payload);
        }
      } catch (e) {
        // Not a JSON message, just emit as 'message'
      }
    });
  }

  send(msg) {
    // Standard send is on the 'message' channel
    if (typeof msg === 'object') {
      bridge.sendMessage('message', JSON.stringify(msg));
    } else {
      bridge.sendMessage('message', msg);
    }
  }

  post(event, data) {
    // Post uses the event name as the channel name
    if (typeof data === 'object') {
      bridge.sendMessage(event, JSON.stringify(data));
    } else {
      bridge.sendMessage(event, data);
    }
  }
}

const channel = new Channel();

module.exports = {
  channel: channel,
  sendMessage: bridge.sendMessage,
  registerChannel: bridge.registerChannel,
  getDataDir: bridge.getDataDir
};
